// scripts/e2e/player.spec.js @ts-check
import{test,expect}from'@playwright/test';import{loginByPromo,openSleepTimer,setSleepPreset,resetSleepTimer,waitForAppReady}from'./utils.js';

test('@webkit application boot has no syntax errors and renders tracks',async({page})=>{const errors=[];page.on('pageerror',error=>errors.push(String(error?.message||error)));await loginByPromo(page);await page.waitForSelector('#album-icons-albums .album-icon',{timeout:10000});await page.waitForSelector('#track-list .track',{timeout:10000});const state=await page.evaluate(()=>({app:typeof window.app?.initialize==='function',albums:!!window.AlbumsManager,player:!!window.playerCore,ui:!!window.PlayerUI,tracks:document.querySelectorAll('#track-list .track').length}));expect(state.app).toBeTruthy();expect(state.albums).toBeTruthy();expect(state.player).toBeTruthy();expect(state.ui).toBeTruthy();expect(state.tracks).toBeGreaterThan(0);expect(errors).toEqual([]);});
test('play track, toggle favorites-only and sleep timer UI',async({page})=>{await loginByPromo(page);await expect(page.locator('#main-block')).toBeVisible();await page.waitForSelector('#track-list .track',{timeout:1e4});const f=page.locator('#track-list .track').first();await f.locator('.like-star').click();await f.click();await expect(page.locator('#lyricsplayerblock')).toBeVisible();await expect(page.locator('#play-pause-icon')).toBeVisible();await page.click('#favorites-btn');await expect(page.locator('#favorites-btn')).toHaveClass(/favorites-active/);await openSleepTimer(page);await setSleepPreset(page,15);await expect(page.locator('#sleep-timer-badge')).toBeVisible();await openSleepTimer(page);await resetSleepTimer(page);await expect(page.locator('#sleep-timer-badge')).toBeHidden()});
test('favoritesOnly: ON with current non-starred jumps to first starred, keeps playing and hides non-starred rows',async({page})=>{await loginByPromo(page);await page.waitForSelector('#track-list .track',{timeout:1e4});const r=page.locator('#track-list .track');await r.nth(1).locator('.like-star').click();await r.nth(0).click();const b=await page.evaluate(()=>String(window.playerCore?.getCurrentTrack?.()?.uid||''));await page.click('#favorites-btn');await page.waitForTimeout(250);const a=await page.evaluate(()=>{const al=[...document.querySelectorAll('#track-list .track[data-uid]')];return{uid:String(window.playerCore?.getCurrentTrack?.()?.uid||''),playing:!!window.playerCore?.isPlaying?.(),len:(window.playerCore?.getPlaylistSnapshot?.()||[]).length,visibleUnfav:al.filter(x=>!x.hasAttribute('data-hidden-by-favonly')).map(x=>x.dataset.uid).filter(u=>!window.playerCore?.isFavorite?.(u))}});expect(a.playing).toBeTruthy();expect(a.uid).not.toBe(b);expect(a.len).toBe(1);expect(a.visibleUnfav.length).toBe(0)});
test('favoritesOnly: OFF restores full playlist without interrupting current track',async({page})=>{await loginByPromo(page);await page.waitForSelector('#track-list .track',{timeout:1e4});const r=page.locator('#track-list .track');await r.nth(0).locator('.like-star').click();await r.nth(0).click();await page.click('#favorites-btn');const oS=await page.evaluate(()=>({uid:String(window.playerCore?.getCurrentTrack?.()?.uid||''),len:(window.playerCore?.getPlaylistSnapshot?.()||[]).length,playing:!!window.playerCore?.isPlaying?.()}));await page.click('#favorites-btn');const ofS=await page.evaluate(()=>({uid:String(window.playerCore?.getCurrentTrack?.()?.uid||''),len:(window.playerCore?.getPlaylistSnapshot?.()||[]).length,playing:!!window.playerCore?.isPlaying?.()}));expect(ofS.playing).toBeTruthy();expect(ofS.uid).toBe(oS.uid);expect(ofS.len).toBeGreaterThan(oS.len)});
test('favoritesOnly: removing last current starred track auto-disables F and keeps current track playing',async({page})=>{await loginByPromo(page);await page.waitForSelector('#track-list .track',{timeout:1e4});const f=page.locator('#track-list .track').first();await f.locator('.like-star').click();await f.click();await page.click('#favorites-btn');await expect(page.locator('#favorites-btn')).toHaveClass(/favorites-active/);const b=await page.evaluate(()=>({uid:String(window.playerCore?.getCurrentTrack?.()?.uid||''),playing:!!window.playerCore?.isPlaying?.()}));await f.locator('.like-star').click();await page.waitForTimeout(300);const a=await page.evaluate(()=>({uid:String(window.playerCore?.getCurrentTrack?.()?.uid||''),playing:!!window.playerCore?.isPlaying?.(),favOn:localStorage.getItem('favoritesOnlyMode')==='1'}));expect(a.playing).toBeTruthy();expect(a.uid).toBe(b.uid);expect(a.favOn).toBeFalsy()});
test('favoritesOnly + shuffle: playlist contains only starred tracks',async({page})=>{await loginByPromo(page);await page.waitForSelector('#track-list .track',{timeout:1e4});const r=page.locator('#track-list .track');await r.nth(0).locator('.like-star').click();await r.nth(1).locator('.like-star').click();await r.nth(0).click();await page.click('#favorites-btn');await page.click('#shuffle-btn');await expect(page.locator('#shuffle-btn')).toHaveClass(/active/);const st=await page.evaluate(()=>{const p=window.playerCore?.getPlaylistSnapshot?.()||[];return{len:p.length,allFav:p.every(t=>window.playerCore?.isFavorite?.(t.uid))}});expect(st.len).toBe(2);expect(st.allFav).toBeTruthy()});
test('favoritesOnly modal: visible non-starred track from another album offers choices and cancel keeps playback',async({page})=>{await loginByPromo(page);const rows=page.locator('#track-list .track');await rows.first().locator('.like-star').click();await rows.first().click();await page.click('#favorites-btn');const before=await page.evaluate(()=>String(window.playerCore?.getCurrentTrackUid?.()||''));await page.locator('#album-icons-albums .album-icon[data-album="ne-vse-ravno"]').click();await expect.poll(()=>page.evaluate(()=>window.AlbumsManager?.getCurrentAlbum?.())).toBe('ne-vse-ravno');const target=page.locator('#track-list .track').first();await expect(target).toBeVisible();await target.click();await expect(page.locator('.modal-bg.active')).toBeVisible();await page.locator('.modal-bg.active [data-choice="cancel"]').click();const after=await page.evaluate(()=>({uid:String(window.playerCore?.getCurrentTrackUid?.()||''),playing:!!window.playerCore?.isPlaying?.()}));expect(after.uid).toBe(before);expect(after.playing).toBeTruthy();});
test('shuffle history: next-next-prev returns to previously played track',async({page})=>{await loginByPromo(page);await page.waitForSelector('#track-list .track',{timeout:1e4});await page.click('#track-list .track >> nth=0');await page.click('#shuffle-btn');await expect(page.locator('#shuffle-btn')).toHaveClass(/active/);const gU=async()=>page.evaluate(()=>String(window.playerCore?.getCurrentTrack?.()?.uid||'')),f=await gU();await page.click('#next-btn');await page.waitForTimeout(200);const s=await gU();await page.click('#next-btn');await page.waitForTimeout(200);const t=await gU();await page.click('#prev-btn');await page.waitForTimeout(200);const b=await gU();expect(f).toBeTruthy();expect(s).toBeTruthy();expect(t).toBeTruthy();expect(b).toBe(s)});
test('logo pulse module is loaded without import/runtime crash',async({page})=>{await loginByPromo(page);const s=await page.evaluate(()=>({hasLogoPulse:!!window.LogoPulse,hasToggle:typeof window.LogoPulse?.toggle==='function',hasUpdate:typeof window.LogoPulse?.updateSettings==='function'}));expect(s.hasLogoPulse).toBeTruthy();expect(s.hasToggle).toBeTruthy();expect(s.hasUpdate).toBeTruthy()});
test('profile smoke: open profile, change avatar/name, no console errors, playback survives',async({page})=>{const er=[];page.on('pageerror',e=>er.push(String(e?.message||e)));page.on('console',m=>{if(m.type()==='error')er.push(m.text())});await loginByPromo(page);await page.waitForSelector('#track-list .track',{timeout:1e4});await page.click('#track-list .track >> nth=0');await page.waitForSelector('#lyricsplayerblock',{timeout:1e4});await page.click('.album-icon[data-akey="__profile__"]');await page.waitForSelector('#tab-account',{timeout:1e4});await page.click('#prof-avatar-btn');await page.waitForSelector('.prof-ava-btn',{timeout:1e4});await page.locator('.prof-ava-btn').nth(1).click();await page.click('#prof-name-edit');await page.fill('#prof-name-inp','Тест-профиль');await page.keyboard.press('Enter');await page.waitForTimeout(300);const st=await page.evaluate(()=>({playing:!!window.playerCore?.isPlaying?.(),name:document.querySelector('#prof-name-inp')?.value||'',avatar:document.querySelector('#prof-avatar-btn')?.textContent||''}));expect(st.playing).toBeTruthy();expect(st.name).toBe('Тест-профиль');expect(st.avatar.length).toBeGreaterThan(0);expect(er.filter(e=>!/(favicon|ERR_ABORTED|ERR_FAILED|Failed to load resource|blocked by CORS policy|status of 404)/i.test(e))).toEqual([])});
test('avatar picker exposes only three free avatars plus server-purchased avatars',async({page})=>{await loginByPromo(page);await page.locator('[data-album="__profile__"]').click();await expect.poll(()=>page.evaluate(()=>window.AlbumsManager?.getCurrentAlbum?.())).toBe('__profile__');await page.evaluate(async()=>{const{shardWallet}=await import('./scripts/app/shards/wallet-service.js');shardWallet.wallet={...shardWallet.wallet,available:true,purchasedAvatarIds:['avatar_dragon'],purchasedAvatars:[{id:'avatar_dragon',avatar:'🐉',title:'Дракон Витрины'}]};});await page.locator('#prof-avatar-btn').click();await expect(page.locator('.prof-ava-btn').first()).toBeVisible();const avatars=await page.locator('.prof-ava-btn').evaluateAll(rows=>rows.map(row=>row.dataset.ava));expect(avatars).toEqual(['😎','🎧','💔','🐉','🔄']);});
test('sleep timer logs feature usage into global stats',async({page})=>{await loginByPromo(page);await page.evaluate(async()=>{window.dispatchEvent(new CustomEvent('player:sleepTimerTriggered',{detail:{targetAt:Date.now(),meta:{mode:'minutes',minutes:1}}}));await window.eventLogger?.flush?.();await window.statsAggregator?.waitForIdle?.();});const features=await page.evaluate(()=>new Promise((resolve,reject)=>{const request=indexedDB.open('MetaDB_v4');request.onerror=()=>reject(request.error);request.onsuccess=()=>{const row=request.result.transaction('stats','readonly').objectStore('stats').get('global');row.onerror=()=>reject(row.error);row.onsuccess=()=>resolve(row.result?.featuresUsed||{});};}));expect(features.sleep_timer||0).toBeGreaterThan(0);});
test('backup restore smoke: import current backup does not stop playback',async({page})=>{await loginByPromo(page);await page.waitForSelector('#track-list .track',{timeout:1e4});await page.click('#track-list .track >> nth=0');await page.waitForSelector('#lyricsplayerblock',{timeout:1e4});const before=await page.evaluate(()=>String(window.playerCore?.getCurrentTrackUid?.()||''));await page.evaluate(async()=>{window.YandexAuth={...(window.YandexAuth||{}),getToken:()=>'e2e-token',getProfile:()=>({yandexId:'e2e'}),getSessionStatus:()=>'active',isTokenAlive:()=>true};const{AccountDataContext}=await import('./scripts/analytics/account-data-boundary.js');await AccountDataContext.switchToYandexAccount('e2e',{adoptLocalData:true});const{BackupVault}=await import('./scripts/analytics/backup-vault.js');const b=await BackupVault.buildBackupObject();b.identity.ownerYandexId='e2e';await BackupVault.importBackupObject(b,'all')});const after=await page.evaluate(()=>({uid:String(window.playerCore?.getCurrentTrackUid?.()||''),playing:!!window.playerCore?.isPlaying?.()}));expect(after.playing).toBeTruthy();expect(after.uid).toBe(before)});
test('sync revision smoke: revision appears in local log',async({page})=>{await loginByPromo(page);const ok=await page.evaluate(async()=>{const m=await import('./scripts/analytics/sync-revisions.js');m.recordSyncRevision({hash:'abc123',domains:['favorites'],uploadedShared:true,reason:'e2e',ok:true});return m.readSyncRevisions()[0]?.reason==='e2e'});expect(ok).toBeTruthy()});
test('shared backup contains playlists but never contains server-mirrored favorites',async({page})=>{await loginByPromo(page);const result=await page.evaluate(async()=>{localStorage.setItem('__favorites_v2__',JSON.stringify([{uid:'GD-01',status:'active',addedAt:Date.now(),updatedAt:Date.now()}]));localStorage.setItem('sc3:playlists',JSON.stringify([{id:'e2e-playlist',name:'E2E',order:['GD-01'],createdAt:Date.now(),updatedAt:Date.now(),deletedAt:0}]));const contract=await import('./scripts/analytics/snapshot-contract.js');const snapshot=contract.collectSharedSnapshotLocalStorage(localStorage);return{favorite:('__favorites_v2__'in snapshot),playlists:JSON.parse(snapshot['sc3:playlists']||'[]')};});expect(result.favorite).toBeFalsy();expect(result.playlists).toHaveLength(1);expect(result.playlists[0].id).toBe('e2e-playlist');});
test('v7 shared materializes playlists but never overwrites local profile or playback',async({page})=>{await loginByPromo(page);await page.locator('#track-list .track').first().click();await expect.poll(()=>page.evaluate(()=>!!window.playerCore?.isPlaying?.())).toBeTruthy();const result=await page.evaluate(async()=>{const{metaDB}=await import('./scripts/analytics/meta-db.js'),module=await import('./scripts/analytics/backup-v7-sync.js');await metaDB.setGlobal('user_profile',{name:'Local E2E',avatar:'💔',createdAt:100,updatedAt:200});const before={uid:window.playerCore.getCurrentTrackUid(),playing:window.playerCore.isPlaying()};await module.applyBackupV7SharedDocument({profile:{name:'Legacy cloud name',avatar:'🎸',createdAt:1,updatedAt:999},playlists:[{id:'shared-e2e',name:'Shared playlist',order:['GD-01'],hidden:[],ops:[],createdAt:100,updatedAt:200,deletedAt:0}]});const profile=(await metaDB.getGlobal('user_profile'))?.value,playlists=JSON.parse(localStorage.getItem('sc3:playlists')||'[]'),after={uid:window.playerCore.getCurrentTrackUid(),playing:window.playerCore.isPlaying()};return{before,after,profile,playlists};});expect(result.after).toEqual(result.before);expect(result.after.playing).toBeTruthy();expect(result.profile).toMatchObject({name:'Local E2E',avatar:'💔'});expect(result.playlists).toHaveLength(1);expect(result.playlists[0].id).toBe('shared-e2e');});
test('legacy cloud cleanup is explicit and cannot control playback',async({page})=>{await loginByPromo(page);const result=await page.evaluate(async()=>{const[sync,actions,render]=await Promise.all([fetch('./scripts/analytics/backup-v7-sync.js').then(r=>r.text()),fetch('./scripts/app/profile/yandex-actions.js').then(r=>r.text()),fetch('./scripts/app/profile/cloud-action-render-kit.js').then(r=>r.text())]);return{helper:sync.includes('cleanupLegacyBackupV6'),serverToken:sync.includes('DELETE_LEGACY_V6'),button:render.includes('legacy-cloud-cleanup'),typedConfirmation:actions.includes('УДАЛИТЬ'),playbackMutation:/\.(play|pause|stop|seek|next|prev|setVolume|setMuted)\s*\(/.test(sync)};});expect(result).toEqual({helper:true,serverToken:true,button:true,typedConfirmation:true,playbackMutation:false});});
test('v7 stats shard projects one immutable event range without server-only state',async({page})=>{await loginByPromo(page);const result=await page.evaluate(async()=>{const module=await import('./scripts/analytics/stats-shard-contract.js'),segment={deviceStableId:'dst_e2e',branchId:'dst_e2e_chain',chainId:'chain_e2e',fromSeq:1,toSeq:3,hash:'abc123',events:[{eventId:'e1',type:'LISTEN_START',uid:'GD-01',platform:'web',data:{quality:'hi',variant:'audio',shuffle:true,favoritesOnly:false}},{eventId:'e2',type:'LISTEN_COMPLETE',uid:'GD-01',timestamp:Date.UTC(2026,0,5,10,1),platform:'web',data:{startedAt:Date.UTC(2026,0,5,10,0),listenedSeconds:60,creditedSegments:[{startedAt:Date.UTC(2026,0,5,10,0),endedAt:Date.UTC(2026,0,5,10,1),creditedMs:60000}],timezoneOffsetMin:0,quality:'hi',variant:'audio',shuffle:true,favoritesOnly:false,isValidListen:true,isFullListen:false}},{eventId:'e3',type:'ACHIEVEMENT_UNLOCK',uid:null,data:{id:'legacy'}}]};const shard=await module.buildStatsProjectionShard(segment);return{eventCount:shard.eventCount,listenMs:shard.projection.listenMs,valid:shard.projection.validPlays,full:shard.projection.fullPlays,starts:shard.projection.starts,quality:shard.projection.dimensions.quality,rangeKey:shard.rangeKey,hash:shard.hash};});expect(result.eventCount).toBe(2);expect(result.listenMs).toBe(60000);expect(result.valid).toBe(1);expect(result.full).toBe(0);expect(result.starts).toBe(1);expect(result.quality.hi).toBe(2);expect(result.rangeKey).toBe('dst_e2e:chain_e2e:1:3:abc123');expect(result.hash).toMatch(/^[a-f0-9]{64}$/);});
test('favoritesOnly survives backup self-restore',async({page})=>{await loginByPromo(page);await page.waitForSelector('#track-list .track',{timeout:1e4});const r=page.locator('#track-list .track');await r.nth(0).locator('.like-star').click();await r.nth(0).click();await page.click('#favorites-btn');await page.evaluate(async()=>{window.YandexAuth={...(window.YandexAuth||{}),getToken:()=>'e2e-token',getProfile:()=>({yandexId:'e2e'}),getSessionStatus:()=>'active',isTokenAlive:()=>true};const{AccountDataContext}=await import('./scripts/analytics/account-data-boundary.js');await AccountDataContext.switchToYandexAccount('e2e',{adoptLocalData:true});const{BackupVault}=await import('./scripts/analytics/backup-vault.js');;const b=await BackupVault.buildBackupObject();b.identity.ownerYandexId='e2e';await BackupVault.importBackupObject(b,'all')});const st=await page.evaluate(()=>({playing:!!window.playerCore?.isPlaying?.(),favOn:localStorage.getItem('favoritesOnlyMode')==='1'}));expect(st.playing).toBeTruthy();expect(st.favOn).toBeTruthy()});
test('album carousel is circular, auto-loads settled album and never stops playback',async({page})=>{await loginByPromo(page);await page.waitForSelector('#album-icons-albums.album-carousel',{timeout:1e4});const initial=await page.evaluate(()=>[...document.querySelectorAll('#album-icons-albums .album-icon')].sort((a,b)=>Number(a.dataset.carouselSlot)-Number(b.dataset.carouselSlot)).map(x=>x.dataset.album));expect(initial).toEqual(['mezhdu-zlom-i-dobrom','odnazhdy-v-skazke','neizvestniy','v-ssore','ne-vse-ravno','golos-dushi','krevetochka']);await page.click('#track-list .track >> nth=0');const before=await page.evaluate(()=>({uid:String(window.playerCore?.getCurrentTrackUid?.()||''),playing:!!window.playerCore?.isPlaying?.()}));await page.locator('#album-icons-albums .album-icon[data-album="ne-vse-ravno"]').click();await expect(page.locator('#album-icons-albums .album-icon[data-album="ne-vse-ravno"]')).toHaveAttribute('data-carousel-center','1');await expect.poll(()=>page.evaluate(()=>String(window.AlbumsManager?.getCurrentAlbum?.()||''))).toBe('ne-vse-ravno');const after=await page.evaluate(()=>({uid:String(window.playerCore?.getCurrentTrackUid?.()||''),playing:!!window.playerCore?.isPlaying?.(),saved:localStorage.getItem('albumCarouselCenter:v1')||''}));expect(after.playing).toBeTruthy();expect(after.uid).toBe(before.uid);expect(after.saved).toBe('ne-vse-ravno')});
test('album gallery visibility persists and special navigation clears album highlight',async({page})=>{await loginByPromo(page);await page.waitForSelector('#cover-wrap',{timeout:1e4});await page.locator('#album-icons-albums [data-carousel-center="1"]').click();await expect(page.locator('#cover-wrap')).toBeHidden();await page.locator('#album-icons-albums .album-icon[data-album="ne-vse-ravno"]').click();await expect.poll(()=>page.evaluate(()=>String(window.AlbumsManager?.getCurrentAlbum?.()||''))).toBe('ne-vse-ravno');await expect(page.locator('#cover-wrap')).toBeHidden();await page.locator('.album-icon[data-album="__favorites__"]').click();await expect.poll(()=>page.evaluate(()=>String(window.AlbumsManager?.getCurrentAlbum?.()||''))).toBe('__favorites__');const state=await page.evaluate(()=>({albumActive:document.querySelectorAll('#album-icons-albums .album-icon.active').length,navActive:document.querySelectorAll('#album-icons-nav .album-icon.active').length,center:document.querySelector('#album-icons-albums [data-carousel-center="1"]')?.dataset.album||''}));expect(state.albumActive).toBe(0);expect(state.navActive).toBe(1);expect(state.center).toBe('ne-vse-ravno')});
test('desktop mouse click opens carousel album and toggles its gallery',async({page})=>{await loginByPromo(page);await page.waitForSelector('#album-icons-albums.album-carousel',{timeout:1e4});const side=page.locator('#album-icons-albums .album-icon[data-album="ne-vse-ravno"]');await side.click();await expect(side).toHaveAttribute('data-carousel-center','1');await expect.poll(()=>page.evaluate(()=>String(window.AlbumsManager?.getCurrentAlbum?.()||''))).toBe('ne-vse-ravno');const center=page.locator('#album-icons-albums [data-carousel-center="1"]');await center.click();await expect(page.locator('#cover-wrap')).toBeHidden();await center.click();await expect(page.locator('#cover-wrap')).toBeVisible()});
test('special navigation has six items and Friends is separated from Game Center',async({page})=>{await loginByPromo(page);const keys=await page.locator('#album-icons-nav .album-icon').evaluateAll(a=>a.map(x=>x.dataset.album));expect(keys).toEqual(['__games__','__friends__','__showcase__','__favorites__','__reliz__','__profile__']);await page.locator('[data-album="__games__"]').click();await expect.poll(()=>page.evaluate(()=>window.AlbumsManager?.getCurrentAlbum?.())).toBe('__games__');await expect(page.locator('#active-album-title')).toContainText('ЗАЛ ВИТРИНЫ');await expect(page.locator('.vf-host-in-friends')).toHaveCount(0);await page.locator('[data-album="__friends__"]').click();await expect.poll(()=>page.evaluate(()=>window.AlbumsManager?.getCurrentAlbum?.())).toBe('__friends__');await expect(page.locator('#active-album-title')).toContainText('ДРУЗЬЯ');await expect(page.locator('.gc-host')).toHaveCount(0)});
test('account-local vault isolates favorites and ledger without stopping playback',async({page})=>{await loginByPromo(page);const first=page.locator('#track-list .track').first();await first.locator('.like-star').click();await first.click();await expect.poll(()=>page.evaluate(()=>!!window.playerCore?.isPlaying?.())).toBeTruthy();const uid=await page.evaluate(()=>String(window.playerCore?.getCurrentTrackUid?.()||''));const chainA=await page.evaluate(async()=>{Object.assign(window.YandexAuth,{getSessionStatus:()=>'active',isTokenAlive:()=>true,getProfile:()=>({yandexId:'account-a'})});const{AccountDataContext}=await import('./scripts/analytics/account-data-boundary.js');await AccountDataContext.switchToYandexAccount('account-a',{adoptLocalData:true});localStorage.setItem('__favorites_v2__',JSON.stringify([{uid:window.playerCore.getCurrentTrackUid(),addedAt:Date.now(),updatedAt:Date.now(),inactiveAt:0,deletedAt:0}]));await window.eventLogger?.flush?.();const value=localStorage.getItem('eventLedger:chainId:v1')||'';await AccountDataContext.saveCurrent();await AccountDataContext.switchToYandexAccount('account-b');return value;});expect(chainA).toMatch(/^chain_/);const accountB=await page.evaluate(()=>({playing:!!window.playerCore?.isPlaying?.(),uid:String(window.playerCore?.getCurrentTrackUid?.()||''),favorites:JSON.parse(localStorage.getItem('__favorites_v2__')||'[]').length,chainId:localStorage.getItem('eventLedger:chainId:v1')||''}));expect(accountB.playing).toBeTruthy();expect(accountB.uid).toBe(uid);expect(accountB.favorites).toBe(0);expect(accountB.chainId).not.toBe(chainA);await page.evaluate(()=>window.AccountDataContext.switchToYandexAccount('account-a'));const accountA=await page.evaluate(()=>({playing:!!window.playerCore?.isPlaying?.(),uid:String(window.playerCore?.getCurrentTrackUid?.()||''),favorites:JSON.parse(localStorage.getItem('__favorites_v2__')||'[]').length,chainId:localStorage.getItem('eventLedger:chainId:v1')||''}));expect(accountA.playing).toBeTruthy();expect(accountA.uid).toBe(uid);expect(accountA.favorites).toBe(1);expect(accountA.chainId).toBe(chainA);});
