test('playback ownership release is foreground-only and does not delay local pause',async({page})=>{await loginByPromo(page);await page.locator('#track-list .track').first().click();await expect.poll(()=>page.evaluate(()=>!!window.playerCore?.isPlaying?.())).toBeTruthy();const result=await page.evaluate(async()=>{const pc=window.playerCore,ownership=window.PlaybackOwnership,original=ownership.release;let calls=0;ownership.release=async()=>{calls++;await new Promise(resolve=>setTimeout(resolve,500));return{ok:true,released:true};};const started=performance.now();pc.pause();const elapsed=performance.now()-started;const paused=!pc.isPlaying();Object.defineProperty(document,'hidden',{configurable:true,get:()=>true});await pc.play();pc.pause();await new Promise(resolve=>setTimeout(resolve,20));ownership.release=original;return{calls,elapsed,paused};});expect(result.paused).toBeTruthy();expect(result.elapsed).toBeLessThan(100);expect(result.calls).toBe(1);});
test('return-here banner requests normal Play only after explicit user click',async({page})=>{await loginByPromo(page);const result=await page.evaluate(async()=>{const module=await import('./scripts/app/playback-return-ui.js');module.initPlaybackReturnUi();const pc=window.playerCore,original=pc.play;let calls=0;pc.play=async()=>{calls++;return false;};window.dispatchEvent(new CustomEvent('playback:ownership-lost',{detail:{playback:{active:true,ownerDeviceId:'dst_remote_e2e',ownerLabel:'Ноутбук'}}}));await new Promise(resolve=>setTimeout(resolve,20));const before={calls,state:module.getPlaybackReturnUiState()};document.querySelector('.playback-return-banner__button')?.click();await new Promise(resolve=>setTimeout(resolve,20));const after={calls,state:module.getPlaybackReturnUiState()};pc.play=original;document.querySelector('.playback-return-banner__close')?.click();return{before,after};});expect(result.before.calls).toBe(0);expect(result.before.state.visible).toBeTruthy();expect(result.after.calls).toBe(1);expect(result.after.state.ownerDeviceId).toBe('dst_remote_e2e');});
test('@webkit iOS keeper cannot recover after ownership transfer pause',async({page})=>{await page.addInitScript(()=>Object.defineProperty(navigator,'userAgent',{configurable:true,get:()=>'Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 Version/18.0 Mobile/15E148 Safari/604.1'}));await loginByPromo(page);await page.locator('#track-list .track').first().click();await expect.poll(()=>page.evaluate(()=>!!window.playerCore?.isPlaying?.())).toBeTruthy();const result=await page.evaluate(async()=>{const pc=window.playerCore;pc.seek(19);const uid=pc.getCurrentTrackUid();pc.pauseForOwnershipTransfer({playback:{active:true,ownerDeviceId:'dst_other_ios_test',ownerLabel:'Компьютер',ownerEpoch:7}});await new Promise(resolve=>setTimeout(resolve,11000));return{uid,afterUid:pc.getCurrentTrackUid(),position:pc.getPosition(),playing:pc.isPlaying()};});expect(result.afterUid).toBe(result.uid);expect(result.position).toBe(19);expect(result.playing).toBeFalsy();});
